import { createHash } from 'node:crypto';
import type { Mapping, TargetMapping } from '../../mappings/define';
import type { ModelsDevModel } from './models-dev-schema';
import { apiCapabilities, selectModels, type DataFile } from './select';
import { resolveField, type FieldResult } from './transforms';

export const HEADER = [
  '// This file is generated by scripts/generate.ts. Do not edit it.',
  '// Change the mapping in mappings/ or the generator, then run `pnpm generate`.',
].join('\n');

const IDENTIFIER = /^[A-Za-z_$][A-Za-z0-9_$]*$/;

function literal(value: string): string {
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

function key(name: string): string {
  return IDENTIFIER.test(name) ? name : literal(name);
}

function pascalCase(id: string): string {
  return id
    .split('-')
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');
}

function indexed({ base, segment }: { base: string; segment: string }): string {
  return `NonNullable<${base}[${literal(segment)}]>`;
}

type PatchNode = { leaf?: FieldResult; children: Map<string, PatchNode> };

function buildTree(results: Array<[path: string, result: FieldResult]>): PatchNode {
  const root: PatchNode = { children: new Map() };
  for (const [path, result] of results) {
    let node = root;
    for (const segment of path.split('.')) {
      let child = node.children.get(segment);
      if (!child) {
        child = { children: new Map() };
        node.children.set(segment, child);
      }
      node = child;
    }
    if (node.children.size > 0)
      throw new Error(`Field "${path}" is also a parent of other fields.`);
    node.leaf = result;
  }
  return root;
}

function renderLeaf({ result, base }: { result: FieldResult; base: string }): string | undefined {
  switch (result.kind) {
    case 'keep':
      return undefined;
    case 'never':
      return 'never';
    case 'union':
      return result.values.map(literal).join(' | ');
    case 'excludeVariants':
      return `Exclude<${base}, { ${key(result.discriminator)}: ${result.values.map(literal).join(' | ')} }>`;
  }
}

/**
 * Renders the fields of a patch object, or `undefined` when no field changes. With `loose`, a
 * nested key that the base does not have is skipped instead of being an error.
 */
function renderFields({
  node,
  base,
  loose = false,
}: {
  node: PatchNode;
  base: string;
  loose?: boolean;
}): string | undefined {
  const fields: Array<string> = [];
  for (const [segment, child] of node.children) {
    const childBase = loose ? `At<${base}, ${literal(segment)}>` : indexed({ base, segment });
    let expression: string | undefined;
    if (child.leaf) {
      expression = renderLeaf({ result: child.leaf, base: childBase });
    } else {
      const nested = renderFields({ node: child, base: childBase, loose });
      if (nested !== undefined) {
        expression = loose
          ? `PatchAt<${base}, ${literal(segment)}, ${nested}>`
          : `Patch<${childBase}, ${nested}>`;
      }
    }
    if (expression !== undefined) fields.push(`${key(segment)}: ${expression};`);
  }
  return fields.length === 0 ? undefined : `{ ${fields.join(' ')} }`;
}

function modelDoc(model: ModelsDevModel): string {
  const lines = [`${model.name}. Released ${model.release_date}.`];
  const reasoning = model.capabilities.reasoning;
  if (reasoning.supported && reasoning.default) {
    lines.push(
      `Default reasoning (models.dev): ${reasoning.default.type} \`${reasoning.default.value}\`.`,
    );
  }
  if (model.status === 'alpha' || model.status === 'beta') lines.push(`Status: ${model.status}.`);
  if (model.status === 'deprecated') {
    const date = model.deprecation_date ? ` on ${model.deprecation_date}` : '';
    lines.push(`@deprecated The model is deprecated${date} (models.dev).`);
  }
  return `/**\n${lines.map((line) => ` * ${line}`).join('\n')}\n */`;
}

type TargetOutput = {
  target: TargetMapping;
  prefix: string;
  baseName: string;
  /** The type of the model IDs that the SDK accepts for the target. */
  modelIdsName: string;
  /** The type of the model IDs of other model types, to their error type. */
  wrongModelsName: string;
  /** The helper type that picks the SDK subtype of a model, when the target has `subTypes`. */
  subTypeName: string | undefined;
  byModelName: string;
  /** Model ID to the type expression of its options. */
  models: Array<{ model: ModelsDevModel; typeName: string }>;
  /** Shape name to its type expression. */
  shapes: Map<string, string>;
  /** Field path to all union values that some model uses, for the checks. */
  values: Map<string, Set<string>>;
};

function buildTarget({
  data,
  mapping,
  target,
}: {
  data: DataFile;
  mapping: Mapping;
  target: TargetMapping;
}): TargetOutput {
  const prefix = pascalCase(target.id);
  const baseName = `${prefix}Base`;
  const output: TargetOutput = {
    target,
    prefix,
    baseName,
    modelIdsName: `${prefix}ModelIds`,
    wrongModelsName: `${prefix}WrongModels`,
    subTypeName: target.subTypes ? `${prefix}SubType` : undefined,
    byModelName: `${target.baseType}ByModel`,
    models: [],
    shapes: new Map(),
    values: new Map(),
  };

  for (const { model } of selectModels({ data, mapping, target })) {
    const capabilities = apiCapabilities({ model, api: target.api });
    const results = Object.entries(target.fields).map(
      ([path, field]) => [path, resolveField({ field, capabilities })] as [string, FieldResult],
    );
    for (const [path, result] of results) {
      if (result.kind !== 'union' && result.kind !== 'excludeVariants') continue;
      const set = output.values.get(path) ?? new Set();
      for (const value of result.values) set.add(value);
      output.values.set(path, set);
    }

    // With SDK subtypes, each model has its own base type. Thus no shapes are shared.
    if (output.subTypeName) {
      const base = `${output.subTypeName}<${literal(model.id)}>`;
      const fields = renderFields({ node: buildTree(results), base, loose: true });
      output.models.push({ model, typeName: fields ? `PatchLoose<${base}, ${fields}>` : base });
      continue;
    }

    const fields = renderFields({ node: buildTree(results), base: baseName });
    if (fields === undefined) {
      output.models.push({ model, typeName: baseName });
      continue;
    }
    // Models with the same patch share one shape. The name comes from a hash of the patch,
    // so that it stays the same when other models change.
    const hash = createHash('sha1').update(fields).digest('hex').slice(0, 8);
    const typeName = `${prefix}_${hash}`;
    output.shapes.set(typeName, `Patch<${baseName}, ${fields}>`);
    output.models.push({ model, typeName });
  }
  return output;
}

export type ProviderSources = {
  /** src/generated/<sdk>/<provider>.ts */
  types: string;
  /** src/generated/<sdk>/<provider>.check.ts */
  check: string;
  /** src/<sdk>/<provider>.ts */
  entry: string;
};

export function emitProvider({
  data,
  mapping,
  mappingFile,
}: {
  data: DataFile;
  mapping: Mapping;
  /**
   * The mapping file, relative to the repo root. The check file imports it to compare the type
   * arguments of each target with the type names.
   */
  mappingFile?: string;
}): ProviderSources {
  const names = mapping.targets.flatMap((target) => [target.baseType, ...(target.aliases ?? [])]);
  const duplicate = names.find((name, index) => names.indexOf(name) !== index);
  if (duplicate) {
    throw new Error(`Mapping of ${mapping.package}: the type "${duplicate}" is exported twice.`);
  }
  const targets = mapping.targets.map((target) => buildTarget({ data, mapping, target }));
  const defaultTarget = mapping.targets.find((target) => target.default) ?? mapping.targets[0]!;

  const types: Array<string> = [
    HEADER,
    `import type * as Sdk from '${mapping.package}';`,
    mapping.targets.some((target) => target.subTypes)
      ? `import type { At, Patch, PatchAt, PatchLoose } from '../../core/patch';`
      : `import type { Patch } from '../../core/patch';`,
  ];
  const exportedNames: Array<string> = [];

  types.push(`import type { KnownModelIds, WrongModels } from '../../core/model-type';`);
  // The model IDs that the SDK knows for other model types. The options of a target give an
  // error type for them, if the target does not also accept the ID.
  const otherEntries = Object.entries(mapping.otherModelIds ?? {}).map(
    ([modelType, expression]) => `${key(modelType)}: KnownModelIds<${expression}>;`,
  );
  types.push(
    [
      `/** The model IDs that the SDK knows for other model types, by model type. */`,
      otherEntries.length > 0
        ? `export type OtherModelIds = {\n${otherEntries.join('\n')}\n};`
        : `export type OtherModelIds = Record<never, never>;`,
    ].join('\n'),
  );

  for (const output of targets) {
    const { target, baseName, byModelName } = output;
    types.push(`// Target "${target.id}": ${target.baseType} (models.dev API "${target.api}").`);
    types.push(`type ${baseName} = Sdk.${target.baseType};`);
    types.push(
      [
        `/** The model IDs that the SDK accepts for this target. */`,
        `export type ${output.modelIdsName} = KnownModelIds<${target.modelIds}>;`,
        `/** The model IDs of other model types that this target does not accept. */`,
        `type ${output.wrongModelsName} = WrongModels<${output.modelIdsName}, OtherModelIds>;`,
      ].join('\n'),
    );
    if (output.subTypeName) {
      types.push(
        [
          `/** The SDK subtype of a model, or the base type for other models. */`,
          `type ${output.subTypeName}<MODEL extends string> = MODEL extends keyof Sdk.${target.subTypes} ? Sdk.${target.subTypes}[MODEL] : ${baseName};`,
        ].join('\n'),
      );
    }
    for (const [name, expression] of [...output.shapes].sort(([a], [b]) => a.localeCompare(b))) {
      types.push(`type ${name} = ${expression};`);
    }
    const entries = output.models.map(
      ({ model, typeName }) => `${modelDoc(model)}\n${key(model.id)}: ${typeName};`,
    );
    if (output.subTypeName) {
      // The models that the SDK knows but models.dev does not keep the SDK's per-model type.
      types.push(`/** The ${target.baseType} for each model ID that models.dev knows. */`);
      types.push(`export type ${byModelName}Generated = {\n${entries.join('\n')}\n};`);
      types.push(`/** The ${target.baseType} for each known model ID. */`);
      types.push(
        `export type ${byModelName} = ${byModelName}Generated & Omit<Sdk.${target.subTypes}, keyof ${byModelName}Generated>;`,
      );
    } else {
      types.push(`/** The ${target.baseType} for each known model ID. */`);
      types.push(`export type ${byModelName} = {\n${entries.join('\n')}\n};`);
    }
    types.push(
      [
        `/**`,
        ` * ${target.baseType} of \`${mapping.package}\`, narrowed to the model.`,
        ` * Without a model, or with an unknown model ID, it is the original SDK type. A model ID`,
        ` * that the SDK knows only for another model type (for example an image model) gives an`,
        ` * error type.`,
        ` */`,
        `export type ${target.baseType}<MODEL extends keyof ${byModelName} | ${output.modelIdsName} | (string & {}) = string> =`,
        `  MODEL extends keyof ${byModelName} ? ${byModelName}[MODEL] : MODEL extends keyof ${output.wrongModelsName} ? ${output.wrongModelsName}[MODEL] : ${baseName};`,
      ].join('\n'),
    );
    exportedNames.push(target.baseType, byModelName);
    for (const alias of target.aliases ?? []) {
      types.push(
        [
          `/** @deprecated Use \`${target.baseType}\` instead. */`,
          `export type ${alias}<MODEL extends keyof ${byModelName} | ${output.modelIdsName} | (string & {}) = string> = ${target.baseType}<MODEL>;`,
        ].join('\n'),
      );
      exportedNames.push(alias);
    }
  }

  const targetEntries = targets
    .map(
      (output) =>
        `${key(output.target.id)}: { base: ${output.baseName}; byModel: ${output.byModelName}; modelIds: ${output.modelIdsName}; wrongModels: ${output.wrongModelsName} };`,
    )
    .join('\n');
  types.push(
    [
      `/** The registry entry of this provider. */`,
      `export type Provider = {`,
      `  optionsKey: ${mapping.optionsKey ? literal(mapping.optionsKey) : 'never'};`,
      `  defaultTarget: ${literal(defaultTarget.id)};`,
      `  targets: {\n${targetEntries}\n};`,
      `};`,
    ].join('\n'),
  );

  return {
    types: `${types.join('\n\n')}\n`,
    check: emitCheck({ mapping, targets, mappingFile }),
    entry: [
      HEADER,
      `export type * from '${mapping.package}';`,
      `export type { ${exportedNames.join(', ')} } from '../generated/${mapping.sdk}/${mapping.provider}';`,
      '',
    ].join('\n\n'),
  };
}

function emitCheck({
  mapping,
  targets,
  mappingFile,
}: {
  mapping: Mapping;
  targets: Array<TargetOutput>;
  mappingFile: string | undefined;
}): string {
  const lines: Array<string> = [
    HEADER,
    '// Compile-time checks: the mapping must match the SDK types. A failed check names the field.',
    `import type * as Sdk from '${mapping.package}';`,
    `import type { Assert, DiscriminatorValues, Equals, Extends, HasKey, IsNever } from '../../core/check';`,
    ...(mappingFile
      ? [`import type MappingFile from '../../../${mappingFile.replace(/\.ts$/, '')}';`]
      : []),
    `import type { ${[
      'OtherModelIds',
      ...targets.flatMap((output) => [
        output.modelIdsName,
        output.byModelName,
        ...(output.subTypeName ? [`${output.byModelName}Generated`] : []),
      ]),
    ].join(', ')} } from './${mapping.provider}';`,
  ];

  // Each list of model IDs must have literals. An empty list means that the SDK changed the type.
  for (const modelType of Object.keys(mapping.otherModelIds ?? {})) {
    lines.push(
      `export type Check_other_model_ids_${modelType.replace(/\W/g, '_')} = Assert<IsNever<OtherModelIds[${literal(modelType)}]> extends false ? true : false>;`,
    );
  }

  targets.forEach((output, index) => {
    const { target } = output;
    const id = target.id.replace(/\W/g, '_');
    const base = `Sdk.${target.baseType}`;

    // The type arguments of `target()` must be the types that the strings name.
    if (mappingFile) {
      const types = `NonNullable<(typeof MappingFile)['targets'][${index}]['~types']>`;
      lines.push(`export type Check_${id}_base_type = Assert<Equals<${types}['base'], ${base}>>;`);
      if (target.subTypes) {
        lines.push(
          `export type Check_${id}_sub_types = Assert<Equals<${types}['subTypes'], Sdk.${target.subTypes}>>;`,
        );
      }
    }

    lines.push(
      `export type Check_${id}_model_ids = Assert<IsNever<${output.modelIdsName}> extends false ? true : false>;`,
    );

    for (const alias of target.aliases ?? []) {
      lines.push(
        `export type Check_${id}_alias_${alias} = Assert<Extends<Sdk.${alias}, ${base}>>;`,
      );
    }

    for (const [path, field] of Object.entries(target.fields)) {
      const name = `Check_${id}_${path.replace(/\W/g, '_')}`;
      let parent = base;
      const segments = path.split('.');
      segments.forEach((segment, index) => {
        const suffix = segments.length > 1 ? `_${index}` : '';
        lines.push(
          `export type ${name}_exists${suffix} = Assert<HasKey<${parent}, ${literal(segment)}>>;`,
        );
        parent = indexed({ base: parent, segment });
      });

      if (field.kind === 'variants') {
        const values = Object.keys(field.variants).map(literal).join(' | ');
        lines.push(
          `export type ${name}_variants = Assert<Extends<${values}, DiscriminatorValues<${parent}, ${literal(field.discriminator)}>>>;`,
        );
        continue;
      }
      const values = output.values.get(path);
      if (field.kind === 'enum' && values && values.size > 0) {
        lines.push(
          `export type ${name}_values = Assert<Extends<${[...values].map(literal).join(' | ')}, ${parent}>>;`,
        );
      }
    }

    lines.push(
      `export type Check_${id}_shapes = Assert<Extends<${output.byModelName}[keyof ${output.byModelName}], ${base}>>;`,
    );
    if (output.subTypeName) {
      // Each generated type must also extend the SDK subtype of its model.
      const generated = `${output.byModelName}Generated`;
      const subTypes = `Sdk.${target.subTypes}`;
      lines.push(
        `export type Check_${id}_model_shapes = Assert<Extends<{ [MODEL in keyof ${generated}]: Extends<${generated}[MODEL], MODEL extends keyof ${subTypes} ? ${subTypes}[MODEL] : ${base}> }[keyof ${generated}], true>>;`,
      );
    }
  });
  return `${lines.join('\n\n')}\n`;
}

export function emitModels({
  providerId,
  provider,
}: {
  providerId: string;
  provider: DataFile['providers'][string];
}): { types: string; entry: string } {
  const models = Object.fromEntries(
    Object.entries(provider.models).sort(([a], [b]) => a.localeCompare(b)),
  );
  const info = { id: provider.id, name: provider.name, doc: provider.doc };
  return {
    types: [
      HEADER,
      `import type { Models as ModelsShape } from '../../core/types';`,
      `/** The provider as models.dev describes it. */`,
      `export const provider = ${JSON.stringify(info)} as const;`,
      `/** The models of the provider, from models.dev. */`,
      `export const models = ${JSON.stringify(models)} as const satisfies ModelsShape;`,
      `export type Models = typeof models;`,
      '',
    ].join('\n\n'),
    entry: [
      HEADER,
      `export { models, provider, type Models } from '../generated/models/${providerId}';`,
      '',
    ].join('\n\n'),
  };
}

export function emitModelsRegistry(providerIds: Array<string>): string {
  const imports = providerIds.map(
    (id, index) => `import type { Models as Models${index} } from './${id}';`,
  );
  const entries = providerIds.map((id, index) => `${key(id)}: Models${index};`);
  return [HEADER, ...imports, `export type ModelsRegistry = {\n${entries.join('\n')}\n};`, ''].join(
    '\n\n',
  );
}

/** The registry of one SDK: provider ID to the provider entry of its generated file. */
export function emitSdkRegistry(mappings: Array<Mapping>): string {
  const sorted = [...mappings].sort((a, b) => a.provider.localeCompare(b.provider));
  const imports = sorted.map(
    (mapping, index) =>
      `import type { Provider as Provider${index} } from './${mapping.provider}';`,
  );
  const entries = sorted.map((mapping, index) => `${key(mapping.provider)}: Provider${index};`);
  return [HEADER, ...imports, `export type Registry = {\n${entries.join('\n')}\n};`, ''].join(
    '\n\n',
  );
}
